<apex:inputText value="{!name}" />
<apex:commandButton value="Query" action="{!query}“ />
</apex:form>
</apex:page>
public class SOQLController {
```

```apex
public String name {
get { return name;}
set { name = value;}
}
public PageReference query() {
```

```apex
String qryString = 'SELECT Id FROM Contact WHERE ' +
